CREATE TABLE IF NOT EXISTS receivables (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), enterprise_id UUID NOT NULL, receivable_no VARCHAR(100) NOT NULL, customer_id UUID NOT NULL, sales_order_id UUID, contract_id UUID, amount NUMERIC(15,2) NOT NULL, paid_amount NUMERIC(15,2) DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'draft', due_date TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE); CREATE INDEX IF NOT EXISTS idx_recv_enterprise ON receivables(enterprise_id); CREATE INDEX IF NOT EXISTS idx_recv_customer ON receivables(customer_id);
		CREATE TABLE IF NOT EXISTS payables (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), enterprise_id UUID NOT NULL, payable_no VARCHAR(100) NOT NULL, supplier_id UUID NOT NULL, purchase_order_id UUID, amount NUMERIC(15,2) NOT NULL, paid_amount NUMERIC(15,2) DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'draft', due_date TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE); CREATE INDEX IF NOT EXISTS idx_pay_enterprise ON payables(enterprise_id); CREATE INDEX IF NOT EXISTS idx_pay_supplier ON payables(supplier_id);
		ALTER TABLE invoices ADD COLUMN IF NOT EXISTS business_type VARCHAR(30); ALTER TABLE invoices ADD COLUMN IF NOT EXISTS business_id UUID;
		ALTER TABLE sales_orders ADD COLUMN IF NOT EXISTS paid_amount NUMERIC(15,2) DEFAULT 0;